   for(int n=1;n<6;n++){int i=n;string command=Id();SocialMutation82 first=null;yield return Call<SocialMutation82>(done=>social[i].HelpTeamLife110(command,team,request,done),row=>{first=row;Check(row.operation=="life.help"&&row.state=="Sent"&&row.received==i&&row.creditedLives==0,"Distinct real helper contributes once without currency/life debit");});yield return Call<SocialMutation82>(done=>social[i].HelpTeamLife110(command,team,request,done),row=>Check(JsonUtility.ToJson(row)==JsonUtility.ToJson(first),"Exact helper command retry returns identical immutable receipt"));yield return Wallet(owners[i],5);}
   yield return Call<SocialLifeRequests110>(done=>social[0].GetTeamLives110(team,0,null,done),row=>Check(row.ownRequest!=null&&row.ownRequest.requestId==request&&row.ownRequest.state=="Claimable"&&row.ownRequest.received==5&&row.ownRequest.remaining==5&&!row.ownRequest.canCollect&&row.ownRequest.collectBlockedReason=="FullLives","Filled request closes Claimable while full wallet preserves all five entitlements"));Passed("Five real free helpers and exact retries close one request without donor cost");
   string c1=Id(),c2=Id(),c3=Id();var binding=new Bindings{recipient=owners[0].View.playerId,donors=owners.Skip(1).Select(v=>v.View.playerId).ToArray(),team=team,requestId=request,claim1=c1,claim2=c2,claim3=c3};File.WriteAllText(Path.Combine(temporary,"ExpectedBindings.json"),JsonUtility.ToJson(binding,true),new UTF8Encoding(false));
   Operate(binding.recipient,3,"room_two");yield return Wallet(owners[0],3);
   Operate(null,-1,null,c1);SocialReply82<SocialMutation82> lost=null;social[0].ClaimTeamLives110(c1,request,x=>lost=x);while(lost==null)yield return null;Check(!lost.Succeeded&&lost.unknown&&lost.error=="SocialHttp503"&&social[0].PendingCommand?.commandId==c1,"Real after-commit503 preserves exact unknown claim intent");string pending=social[0].PendingCommand.body;
   social[0].Dispose();social[0]=Client(owners[0],vaults[0],Path.Combine(vaultRoot,"social_0.sealed"));report.protectedReconstructionCount++;Check(social[0].PendingCommand?.body==pending&&social[0].PendingCommand.commandId==c1,"Fresh actual client reopens protected exact pending claim");SocialMutation82 original=null;yield return Call<SocialMutation82>(done=>social[0].ResumePending(done),row=>{original=row;Check(row.state=="PartiallyCollected"&&row.creditedLives==2&&row.claimed==2&&row.remaining==3&&row.lives==5,"Same-ID recovered claim delivers two and retains banked three");});Check(social[0].PendingCommand==null,"Confirmed recovery clears exact protected outbox");yield return Wallet(owners[0],5);Passed("Actual after-commit loss and protected client reconstruction recover one partial claim");
   SocialMutation82 deferred=null;yield return Call<SocialMutation82>(done=>social[0].ClaimTeamLives110(c2,request,done),row=>{deferred=row;Check(row.state=="Deferred"&&row.creditedLives==0&&row.remaining==3,"Full wallet confirms Deferred0 without destroying banked entitlement");});yield return Call<SocialMutation82>(done=>social[0].ClaimTeamLives110(c2,request,done),row=>Check(JsonUtility.ToJson(row)==JsonUtility.ToJson(deferred),"Exact confirmed Deferred0 retry keeps the same immutable zero-credit receipt"));yield return Call<SocialOwnedLives110>(done=>social[0].GetOwnedLives110(0,done),row=>Check(row.requests.Any(v=>v.requestId==request&&v.remaining==3),"Owner list retains partial banked remainder"));
   yield return Call<SocialMutation82>(done=>social[0].ManageMember("transfer",Id(),team,owners[1].View.playerId,done),row=>Check(row.action=="transfer"&&row.playerId==owners[1].View.playerId,"Actual owner transfers leadership before leaving its nonempty team"));yield return Call<SocialMutation82>(done=>social[0].LeaveTeam(Id(),team,done),row=>Check(row.state=="Left","Recipient leaves team through real durable social operation"));yield return Call<SocialOwnedLives110>(done=>social[0].GetOwnedLives110(0,done),row=>Check(row.requests.Any(v=>v.requestId==request&&v.remaining==3),"Owned entitlement survives confirmed team leave"));
