  public static void Run(){
   output=Path.GetFullPath(Environment.GetEnvironmentVariable("HOTR_REVIEW110_HTTP_OUT")??throw new InvalidOperationException("Explicit110output required"));temporary=Path.GetFullPath(Environment.GetEnvironmentVariable("HOTR_REVIEW110_HTTP_PRIVATE")??throw new InvalidOperationException("Explicit private110 fixture required"));CheckPath();report=new Report{unity=Application.unityVersion};connection=JsonUtility.FromJson<Connection>(File.ReadAllText(Path.Combine(temporary,"connection.json")));var uri=new Uri(connection.origin);Check(uri.Scheme=="http"&&uri.Host=="127.0.0.1"&&uri.Port>0&&connection.actualBackend&&!connection.replayEnabled&&!connection.providersEnabled&&!connection.productionEnabled,"Exact owned loopback actual service is required");if(!System.Text.RegularExpressions.Regex.IsMatch(connection.runId??"","\\A[a-f0-9]{32}\\z"))throw new InvalidOperationException("ExactRunIdRequired110");vaultRoot=Path.GetFullPath("../.verification-cache/Launch82/TeamHelp110/"+connection.runId);if(Directory.Exists(vaultRoot))throw new InvalidOperationException("FreshIgnoredVaultFixtureRequired110");Directory.CreateDirectory(vaultRoot);profiles=Digest(Path.Combine(Application.persistentDataPath,"Profiles"));server=Digest(Path.Combine(Application.persistentDataPath,"ServerReview"));settings=Digest("ProjectSettings");hadLanguage=PlayerPrefs.HasKey(GameLocale.PreferenceKey);language=PlayerPrefs.GetInt(GameLocale.PreferenceKey,-1);deadline=EditorApplication.timeSinceStartup+300;stack.Push(Flow());EditorApplication.update+=Tick;
  }
  static void CheckPath(){string root=Path.GetFullPath("../.verification-cache/Review110/HelpHTTP")+Path.DirectorySeparatorChar;if(!temporary.StartsWith(root,StringComparison.OrdinalIgnoreCase)||!File.Exists(Path.Combine(temporary,"connection.json")))throw new InvalidOperationException("Fresh110privatefixture required");}
  static void Tick(){try{if(EditorApplication.timeSinceStartup>deadline)throw new TimeoutException("Bounded Help110actual HTTP suite timed out");if(waiting!=null){if(!waiting.isDone)return;waiting=null;}if(stack.Count==0){Finish();return;}var top=stack.Peek();if(!top.MoveNext()){stack.Pop();(top as IDisposable)?.Dispose();}else if(top.Current is IEnumerator child)stack.Push(child);else if(top.Current is AsyncOperation operation)waiting=operation;while(dispatched.Count>0)stack.Push(dispatched.Dequeue());}catch(Exception error){report.errors.Add(error.GetType().Name+": "+error.Message);Finish();}}
  static void Finish(){if(finished)return;finished=true;EditorApplication.update-=Tick;while(stack.Count>0)(stack.Pop()as IDisposable)?.Dispose();while(dispatched.Count>0)(dispatched.Dequeue()as IDisposable)?.Dispose();foreach(var client in clients){report.socialRequests+=client.VerificationRequests;report.socialStatuses.AddRange(client.VerificationStatuses);}foreach(var identity in identities){report.signedRequests+=identity.VerificationRequestCount;report.signedStatuses.AddRange(identity.VerificationStatuses);}for(int n=cleanup.Count-1;n>=0;n--)try{cleanup[n].Dispose();}catch(Exception){report.errors.Add("Owned HTTP cleanup failed");}try{report.ordinaryProfilesPreserved=profiles==Digest(Path.Combine(Application.persistentDataPath,"Profiles"));report.serverReviewPreserved=server==Digest(Path.Combine(Application.persistentDataPath,"ServerReview"));report.settingsPreserved=settings==Digest("ProjectSettings");report.languagePreferencePreserved=hadLanguage==PlayerPrefs.HasKey(GameLocale.PreferenceKey)&&language==PlayerPrefs.GetInt(GameLocale.PreferenceKey,-1);Check(report.ordinaryProfilesPreserved&&report.serverReviewPreserved&&report.settingsPreserved&&report.languagePreferencePreserved,"Ordinary data/settings/language remain byte-identical");}catch(Exception){report.errors.Add("Preservation audit failed");}report.utc=DateTime.UtcNow.ToString("o");report.status=report.errors.Count==0?"PASS_NATIVE_TEAMS_CHAT_HELP110_HTTP":"FAIL_NATIVE_TEAMS_CHAT_HELP110_HTTP";Directory.CreateDirectory(Path.Combine(output,"Native"));File.WriteAllText(Path.Combine(output,"Native","TeamsChatHelp110_HTTP.json"),JsonUtility.ToJson(report,true),new UTF8Encoding(false));EditorApplication.Exit(report.errors.Count==0?0:1);}
